// Cloudflare.Env is generated by `npm run types`; incomplete deployments stay
// readable while sign-in remains disabled until all required settings exist.
export type Bindings = Partial<Cloudflare.Env>;

export interface AuthConfig {
  origin: string;
  ownerId: string;
  clientId: string;
  clientSecret: string;
  sessionSecret: string;
  appSlug: string | null;
}

export function authConfig(env: Bindings): AuthConfig | null {
  try {
    const origin = new URL(env.APP_ORIGIN ?? '');
    if (origin.protocol !== 'https:' || origin.username || origin.password ||
      origin.pathname !== '/' || origin.search || origin.hash) return null;
    if (!/^[1-9]\d{0,15}$/.test(env.GITHUB_OWNER_ID ?? '') ||
      !Number.isSafeInteger(Number(env.GITHUB_OWNER_ID))) return null;
    if (!/^[A-Za-z0-9_]{8,100}$/.test(env.GITHUB_CLIENT_ID ?? '')) return null;
    if (!env.GITHUB_CLIENT_SECRET || env.GITHUB_CLIENT_SECRET.length < 20 || env.GITHUB_CLIENT_SECRET.length > 512) return null;
    // Canonical unpadded base64url encoding of 32 random bytes.
    if (env.SESSION_SECRET?.length !== 43 || !/^[A-Za-z0-9_-]{42}[AEIMQUYcgkosw048]$/.test(env.SESSION_SECRET)) return null;
    const slug = env.GITHUB_APP_SLUG;
    return {
      origin: origin.origin, ownerId: env.GITHUB_OWNER_ID!, clientId: env.GITHUB_CLIENT_ID!,
      clientSecret: env.GITHUB_CLIENT_SECRET, sessionSecret: env.SESSION_SECRET!,
      appSlug: slug && /^[a-z0-9]+(?:-[a-z0-9]+)*$/.test(slug) && slug.length <= 100 ? slug : null,
    };
  } catch { return null; }
}
